mapper.select:
select day(browse_date)
from house_history
where user_id = #{userId}
  and browse_date between #{startDate} and #{endDate}
group by browse_date
order by browse_date asc

select hh.id as historyId, hh.house_id as houseId, hh.browse_date as browseDate, hh.last_browse_time as lastBrowseTime, round(h.price / 100.0, 2) as price, concat('https://picsum.photos/seed/history-', hh.house_id, '/480/320') as cover from house_history hh join house h on h.id = hh.house_id where hh.user_id = #{userId}
and hh.browse_date = #{browseDate}
order by hh.browse_date desc, hh.last_browse_time desc, hh.id desc
